/* From Uiverse.io by xetrov47  - Tags: simple, input, search */
.__UIV_SCOPE__ .search {
  display: flex;
  align-items: center;
  text-align: center;
}

.__UIV_SCOPE__ .search__input {
  font-family: inherit;
  font-size: inherit;
  border: 1px solid #767676;
  color: #767676;
  padding: 5px 10px;
  border-radius: 4px;
  margin-right: -1.5rem;
  height: 30px;
  width: 15rem;
}

.__UIV_SCOPE__ .search__input::-webkit-input-placeholder {
  font-weight: 400;
  color: #767676;
  font-size: 14px;
}

.__UIV_SCOPE__ .search__button {
  border: none;
  background-color: #fff;
  margin-top: 0.1em;
}

.__UIV_SCOPE__ .search__button:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .search input:focus {
  outline: none;
}
